const BoopFace = (() => {
  const HTMLElementBase = typeof HTMLElement === 'undefined' ? class {} : HTMLElement;
  const EASE = {
    outQuint: t => 1 - Math.pow(1 - t, 5),
    inOutCubic: t => t < 0.5 ? 4*t*t*t : 1 - Math.pow(-2*t + 2, 3)/2,
  };

  const POSES = {
    idle: {
      w: 54, h: 58, rx: 27,
      topY: -36, bottomY: 36,
      topAL: 0, topAR: 0, bottomAL: 0, bottomAR: 0,
      scale: 1,
    },
    happy: {
      w: 58, h: 58, rx: 29,
      topY: -36, bottomY: 0,
      topAL: 0, topAR: 0, bottomAL: 0, bottomAR: 0,
      scale: 1,
    },
    sad: {
      w: 58, h: 58, rx: 29,
      topY: -5, bottomY: 36,
      topAL: -16, topAR: 16, bottomAL: 0, bottomAR: 0,
      scale: 1,
    },
    angry: {
      w: 58, h: 58, rx: 29,
      topY: -5, bottomY: 36,
      topAL: 16, topAR: -16, bottomAL: 0, bottomAR: 0,
      scale: 1,
    },
    sleepy: {
      w: 58, h: 56, rx: 28,
      topY: 0, bottomY: 36,
      topAL: 0, topAR: 0, bottomAL: 0, bottomAR: 0,
      scale: 1,
    },
    input: {
      w: 12, h: 78, rx: 2,
      topY: -44, bottomY: 44,
      topAL: 0, topAR: 0, bottomAL: 0, bottomAR: 0,
      scale: 1,
    },
    // Same eye as sleepy; the lids meet in a thin slit instead of squashing it.
    sleep: {
      w: 58, h: 56, rx: 28,
      topY: 7, bottomY: 14,
      topAL: 0, topAR: 0, bottomAL: 0, bottomAR: 0,
      scale: 1,
    },
    surprise: {
      w: 68, h: 68, rx: 34,
      topY: -40, bottomY: 40,
      topAL: 0, topAR: 0, bottomAL: 0, bottomAR: 0,
      scale: 1,
    },
  };

  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  const lerp = (a, b, t) => a + (b - a) * t;
