  const parseSize = value => {
    const text = String(value ?? '').trim();
    if (!/^(?:\d+(?:\.\d+)?|\.\d+)(?:px)?$/i.test(text)) return DEFAULT_SIZE;
    const numeric = Number.parseFloat(text);
    return Number.isFinite(numeric) && numeric > 0 ? numeric : DEFAULT_SIZE;
