    if (typeof face._noteEnvironmentActivity === 'function') face._noteEnvironmentActivity(event);
    else face.noteActivity();
  });
  const handleGlobalKeyDown = event => forEachConnectedFace(face => {
    if (typeof face._noteEnvironmentActivity === 'function') face._noteEnvironmentActivity(event);
    else face.noteActivity();
