  const base = Array.isArray(tune.colors) && tune.colors.length === 4 ? tune.colors : look.base;
  return { ...look, base, antenna: [base[0], base[1], base[3]], linear: tune.vertical ? 'vertical' : look.linear, shade: tune.depth, tune };
}

