  },
  cricket({ colors: [seam, stitch] }) {
    // A raised seam arching over the forehead with three rows of stitches each side.
    const y = (x, lift) => 84 - Math.sin(x / 240 * Math.PI) * 26 + lift;
    const curve = lift => {
      let d = '';
      for (let x = -4; x <= 244; x += 8) d += `${x < 0 ? 'M' : 'L'}${x} ${n(y(x, lift))}`;
